import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Plugins","description":"","frontmatter":{},"headers":[],"relativePath":"guide/plugins-and-presets.md","filePath":"guide/plugins-and-presets.md"}`),a={name:`guide/plugins-and-presets.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to “Plugins”">​</a></h1><p>Vibator ships no rules of its own. These packages, together called the gate, are the official plugins and presets: they give you a working set of rules from day one. Every package is independent, install only the ones you want.</p><p>The <a href="/guide/getting-started.html#quick-setup">quick setup</a> wires them up for you.</p><h2 id="the-packages" tabindex="-1">The packages <a class="header-anchor" href="#the-packages" aria-label="Permalink to “The packages”">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>What it adds</th></tr></thead><tbody><tr><td><a href="/reference/biome-rule.html"><code>@vibator/biome</code></a></td><td>The <code>biome</code> rule: formatting and lint findings from <a href="https://biomejs.dev" target="_blank" rel="noreferrer">Biome</a>.</td></tr><tr><td><a href="/reference/knip-rule.html"><code>@vibator/knip</code></a></td><td>The <code>knip</code> rule: unused files, exports, and dependencies from <a href="https://knip.dev" target="_blank" rel="noreferrer">Knip</a>.</td></tr><tr><td><a href="/reference/depcruise-rule.html"><code>@vibator/depcruise</code></a></td><td>The <code>depcruise</code> rule: ruleset violations from <a href="https://github.com/sverweij/dependency-cruiser" target="_blank" rel="noreferrer">dependency-cruiser</a>.</td></tr><tr><td><a href="/reference/recommended-namespace.html"><code>@vibator/recommended</code></a></td><td>The recommended general-purpose rules.</td></tr><tr><td><a href="/reference/gate-package.html"><code>@vibator/gate</code></a></td><td>The shared Biome, dependency-cruiser, and TypeScript presets.</td></tr><tr><td><code>@vibator/create-gate</code></td><td>The wizard that writes the configuration.</td></tr></tbody></table><h2 id="why-run-tools-through-vibator" tabindex="-1">Why run tools through vibator? <a class="header-anchor" href="#why-run-tools-through-vibator" aria-label="Permalink to “Why run tools through vibator?”">​</a></h2><p>Nothing forces you to, these tools run fine on their own, and you can keep them that way.</p><p>Running them through vibator changes three things:</p><ul><li><strong>One command, one report.</strong> Every finding arrive in a single run and a single output, instead of a chain of npm scripts each with its own format. The output is <a href="/reference/command-line.html#reporters">SARIF-compatible</a>, so it drops into the code-scanning and CI workflows you already have.</li><li><strong>One entry point.</strong> <code>.vibator.json</code> decides which tools run and at what severity. Their options can live inline or stay in the config files you already have.</li></ul>`,9)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};